-cmp_order(const fvalue_t *a, const fvalue_t *b, int *cmp)
+float_cmp_order(const fvalue_t *a, const fvalue_t *b, int *cmp)
+{
+	gchar string[G_ASCII_DTOSTR_BUF_SIZE];
+	gdouble a_floating, b_floating;
+	char *endptr = NULL;
+
+	/* Convert the double-precision floating point value to a single-precision
+	 * floating point string representation first. This will compare the same
+	 * value as being printed for a FT_FLOAT value.
+	 */
+	g_ascii_formatd(string, sizeof(string), "%." G_STRINGIFY(FLT_DIG) "g", a->value.floating);
+	a_floating = g_ascii_strtod(string, &endptr);
+	g_ascii_formatd(string, sizeof(string), "%." G_STRINGIFY(FLT_DIG) "g", b->value.floating);
+	b_floating = g_ascii_strtod(string, &endptr);
+
+	if (a_floating < b_floating)
+		*cmp = -1;
+	else if (a_floating > b_floating)
+		*cmp = 1;
+	else
+		*cmp = 0;
+	return FT_OK;
+}
+
